SELECT 'fungsi baru ada' AS butir, IF((SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_pihak_jumlah' AND MD5(routine_definition)='8984f41d70223c83bc6af72dd8f40a74') OR (routine_name='isian_rtf_pihak_identitas' AND MD5(routine_definition)='4ee30bc89c1585852bafc1ddf67ff4c2') OR (routine_name='isian_rtf_pihak_nama_semua' AND MD5(routine_definition)='b777c5c59eb9b85066e107b51d897288') OR (routine_name='isian_rtf_pihak_kaki' AND MD5(routine_definition)='a467210c95e365d59e920e187510a1e6') OR (routine_name='isian_rtf_pihak_sebut' AND MD5(routine_definition)='88aa93cdbe6f4e6afdefd62d50d07d3a'))) = 5, 1, 0) AS cocok;
