SELECT 'fungsi jalan' AS butir, IF(isian_rtf_romawi(11) = 'XI' AND isian_rtf_romawi(25) = 'XXV' AND isian_rtf_romawi(12) = 'XII' AND isian_rtf_pihak_utama(0, 1, 1, 'Pemohon', 'tempat kediaman di') = '' AND isian_rtf_pihak_nama(0, 2, 1, 'Tergugat') = '' AND isian_rtf_pihak_urutan(0, 1, 'Pemohon') = '' AND isian_rtf_pihak_tambahan(0, 4) = '' AND isian_rtf_pihak_identitas(0, 2, 'Tergugat', 'tempat kediaman di', '', '') = '' AND isian_rtf_pihak_nama_semua(0, 1, 'Pemohon') = '' AND isian_rtf_pihak_kaki(0, 1) IS NULL AND isian_rtf_pihak_sebut(0, 4) = '' AND isian_rtf_pihak_jumlah(0, 1) = 0, 1, 0) AS cocok;
SELECT IF((SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=3520 AND MD5(nama)='6c508f10115ee0a09fa42f2a4b54c1db' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='9d15c4ee2b501bf7240d57a22410f3c1' AND default_data IS NULL) OR (no_var=3521 AND MD5(nama)='f7221980785ab44623a1db4d7cbcf237' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='51cb9e67c0699d9605d907b7fc78e5ba' AND default_data IS NULL) OR (no_var=3522 AND MD5(nama)='5fe398d2a01de6b97473f61a50aaca43' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='1fff83bd72042febdbf19e0fb1ff67e7' AND default_data IS NULL) OR (no_var=3523 AND MD5(nama)='3d1519ddb49918a36ee4276f9d026288' AND data_type='data_sql' AND data_tabel IS NULL AND data_kolom IS NULL AND urutan_data IS NULL AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND MD5(sql_query)='837d4370335ff33347005180db40cb99' AND default_data IS NULL) OR (no_var=7036 AND MD5(nama)='8244b03f29fad895a0acce10cb1d8a62' AND data_type='data_sql' AND MD5(sql_query)='b8329170fe7fdb6c5874793dd071b438') OR (no_var=7037 AND MD5(nama)='29a4e87b30c5700111feb37a19080138' AND data_type='data_sql' AND MD5(sql_query)='cd7eec3799be23a6240c0ff79a0f9ff6') OR (no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='f548b43be1206974a88aa1cd84b66822') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='485001ad3b68a7ab053d8e875ca001c4') OR (no_var=7097 AND MD5(nama)='6381b070ba833efd8b2872ed0667be82' AND data_type='data_sql' AND MD5(sql_query)='813c45f63d3901ec0e111a805cf9fe1b') OR (no_var=7098 AND MD5(nama)='338fbfd71f0675334fb9c06d7e56812c' AND data_type='data_sql' AND MD5(sql_query)='ee3eaf5a192a8f761a117251efda901d') OR (no_var=7148 AND MD5(nama)='f64967b055eae3dac1869586e9a13e4b' AND data_type='data_sql' AND MD5(sql_query)='4e6ec49f488b15c16bdee4843746920d') OR (no_var=7149 AND MD5(nama)='8cbe408b8b15295573027e586753bfa3' AND data_type='data_sql' AND MD5(sql_query)='838d56ebef8a83cf18852eae40734a3e') OR (no_var=7152 AND MD5(nama)='b97816b0be3d010401f04d239a3e083c' AND data_type='data_sql' AND MD5(sql_query)='52fdf197751105d9d8e547f49d00d2ae') OR (no_var=8516 AND MD5(nama)='d7c00de1a231d9253bccfb020bc50dfa' AND data_type='data_sql' AND MD5(sql_query)='3abaa6f3d51f12b12ed94ea44bb331dd'))) = 14 AND (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_pihak_jumlah' AND MD5(routine_definition)='8984f41d70223c83bc6af72dd8f40a74') OR (routine_name='isian_rtf_pihak_identitas' AND MD5(routine_definition)='4ee30bc89c1585852bafc1ddf67ff4c2') OR (routine_name='isian_rtf_pihak_nama_semua' AND MD5(routine_definition)='b777c5c59eb9b85066e107b51d897288') OR (routine_name='isian_rtf_pihak_kaki' AND MD5(routine_definition)='a467210c95e365d59e920e187510a1e6') OR (routine_name='isian_rtf_pihak_sebut' AND MD5(routine_definition)='88aa93cdbe6f4e6afdefd62d50d07d3a'))) = 5 AND (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_pihak_utama' AND MD5(routine_definition)='d2fa4361de6fb016c488aad0fc8a1793') OR (routine_name='isian_rtf_pihak_nama' AND MD5(routine_definition)='72f3dcd1746a45a2b4c0e399dc044ee4') OR (routine_name='isian_rtf_pihak_urutan' AND MD5(routine_definition)='8f201d025843668a5f3daac33fa4bb66') OR (routine_name='isian_rtf_pihak_tambahan' AND MD5(routine_definition)='9cf2a80618cfee32d3b096c4b1c83dc8'))) = 4 AND isian_rtf_romawi(11) = 'XI' AND isian_rtf_romawi(25) = 'XXV' AND isian_rtf_romawi(12) = 'XII' AND isian_rtf_pihak_utama(0, 1, 1, 'Pemohon', 'tempat kediaman di') = '' AND isian_rtf_pihak_nama(0, 2, 1, 'Tergugat') = '' AND isian_rtf_pihak_urutan(0, 1, 'Pemohon') = '' AND isian_rtf_pihak_tambahan(0, 4) = '' AND isian_rtf_pihak_identitas(0, 2, 'Tergugat', 'tempat kediaman di', '', '') = '' AND isian_rtf_pihak_nama_semua(0, 1, 'Pemohon') = '' AND isian_rtf_pihak_kaki(0, 1) IS NULL AND isian_rtf_pihak_sebut(0, 4) = '' AND isian_rtf_pihak_jumlah(0, 1) = 0, 'SEMUA COCOK', 'TIDAK COCOK') AS hasil;
